DOC_RE = "\\b[Dd][Oo][Cc]-\\d+\\b"
INV_RE = "\\b[Ii][Nn][Vv]-\\d+\\b"
DOC_WORD_RE = "\\b[Dd]ocument\\s+\\d+\\b"
INV_WORD_RE = "\\b[Ii]nvoice\\s+\\d+\\b"

ENTER_WORDS = ["enter", "record", "ledger"]
SCHEDULE_WORDS = [
    "schedule",
    "set up payment",
    "set up the payment",
    "pay the payment",
    "payment for",
    "work out what we owe",
    "what we owe",
]
AMOUNT_WORDS = [
    "amount due",
    "what we owe",
    "owe on",
    "due on",
    "when it's due",
    "when it’s due",
    "when due",
]
CANCEL_WORDS = ["cancel", "cancell", "disput", "delete", "hold"]

async def decide(request, kit):
    text = request
    lower = text.lower()

    def clean_number(value):
        if isinstance(value, float):
            whole = int(value)
            if value == whole:
                return whole
        return value

    def normalize_id(raw, prefix):
        raw_text = raw.strip()
        low = raw_text.lower()
        if prefix == "DOC":
            if low.startswith("doc-"):
                parts = raw_text.split("-")
                if len(parts) > 1:
                    return "DOC-" + parts[-1]
            if low.startswith("doc "):
                parts = raw_text.split()
                if len(parts) > 1:
                    return "DOC-" + parts[-1]
            if low.startswith("document"):
                parts = raw_text.split()
                if len(parts) > 1:
                    return "DOC-" + parts[-1]
        if prefix == "INV":
            if low.startswith("inv-"):
                parts = raw_text.split("-")
                if len(parts) > 1:
                    return "INV-" + parts[-1]
            if low.startswith("inv "):
                parts = raw_text.split()
                if len(parts) > 1:
                    return "INV-" + parts[-1]
            if low.startswith("invoice"):
                parts = raw_text.split()
                if len(parts) > 1:
                    return "INV-" + parts[-1]
        return raw_text.upper()

    def gather_ids(patterns, prefix):
        items = []
        for pattern in patterns:
            found = kit.find(pattern, text)
            for raw in found:
                norm = normalize_id(raw, prefix)
                if norm not in items:
                    items.append(norm)
        return items

    def find_positions(phrases):
        positions = []
        for phrase in phrases:
            start = 0
            while True:
                pos = lower.find(phrase, start)
                if pos == -1:
                    break
                positions.append(pos)
                start = pos + 1
        return positions

    async def choose_target(cands, phrases, kind):
        if len(cands) == 1:
            return cands[0]

        positions = find_positions(phrases)
        if len(positions) > 0:
            target_pos = min(positions)
            best_score = None
            best_cands = []

            for cand in cands:
                cand_low = cand.lower()
                start = 0
                cand_score = None

                while True:
                    pos = lower.find(cand_low, start)
                    if pos == -1:
                        break
                    score = (abs(pos - target_pos), 0 if pos >= target_pos else 1, pos)
                    if cand_score is None or score < cand_score:
                        cand_score = score
                    start = pos + 1

                if cand_score is not None:
                    if best_score is None or cand_score < best_score:
                        best_score = cand_score
                        best_cands = [cand]
                    elif cand_score == best_score:
                        best_cands.append(cand)

            if len(best_cands) == 1:
                return best_cands[0]

            if len(best_cands) > 1:
                cands = best_cands

        criteria = {}
        for cand in cands:
            criteria[cand] = "the request is about " + cand
        criteria["none"] = "none of these ids fits"

        asked = await kit.ask(
            {"request": text, "kind": kind, "candidates": cands},
            {
                "pick": {
                    "type": "choice",
                    "instructions": "Choose the likeliest " + kind + " id the user means. If none of the candidates fits, choose none.",
                    "criteria": criteria,
                }
            },
        )
        choice = asked["pick"]["choice"]
        if choice in cands:
            return choice
        return None

    has_cancel = any(word in lower for word in CANCEL_WORDS)
    has_status = (
        "status" in lower
        or "entered yet" in lower
        or "been entered" in lower
        or "already entered" in lower
    )
    has_schedule_status = (
        "been scheduled" in lower
        or "has the payment" in lower
        or "is the payment" in lower
        or "payment been scheduled" in lower
        or "already scheduled" in lower
    )
    has_enter = any(word in lower for word in ENTER_WORDS)
    has_schedule = any(word in lower for word in SCHEDULE_WORDS)
    has_amount = any(word in lower for word in AMOUNT_WORDS)

    doc_ids = gather_ids([DOC_RE, DOC_WORD_RE], "DOC")
    inv_ids = gather_ids([INV_RE, INV_WORD_RE], "INV")

    if has_cancel or has_status or has_schedule_status:
        return {"handoff": "Status, cancel, or dispute requests are out of scope."}

    if has_enter and len(doc_ids) > 0:
        doc_id = await choose_target(doc_ids, ["enter", "record"], "document")
        if doc_id is None:
            return {"handoff": "I couldn't identify which document to enter."}
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or parsed.get("error"):
            return {"handoff": "I couldn't parse document " + doc_id + "."}
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + doc_id + " in the ledger.",
        }

    if has_schedule and len(inv_ids) > 0:
        invoice_id = await choose_target(
            inv_ids,
            [
                "schedule",
                "set up payment",
                "set up the payment",
                "pay the payment",
                "payment for",
                "work out what we owe",
                "what we owe",
                "owe on",
                "due on",
                "when it's due",
                "when it’s due",
                "when due",
                "payment",
                "pay",
            ],
            "invoice",
        )
        if invoice_id is None:
            return {"handoff": "I couldn't identify which invoice to schedule."}
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or payable.get("error"):
            return {"handoff": "I couldn't calculate the payment for " + invoice_id + "."}
        amount_usd = clean_number(payable["amount_usd"])
        pay_on = payable["pay_on"]
        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": amount_usd,
                "pay_on": pay_on,
            },
            "reply": "Scheduled payment for " + invoice_id + " for $" + str(amount_usd) + " on " + pay_on + ".",
        }

    if has_amount and len(inv_ids) > 0:
        invoice_id = await choose_target(
            inv_ids,
            [
                "amount due",
                "what we owe",
                "owe on",
                "due on",
                "when it's due",
                "when it’s due",
                "when due",
                "status",
                "invoice",
            ],
            "invoice",
        )
        if invoice_id is None:
            return {"handoff": "I couldn't identify which invoice amount to check."}
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or payable.get("error"):
            return {"handoff": "I couldn't calculate the amount due for " + invoice_id + "."}
        amount_usd = clean_number(payable["amount_usd"])
        pay_on = payable["pay_on"]
        return {
            "handoff": "Invoice " + invoice_id + " is due for $" + str(amount_usd) + " on " + pay_on + "; amount/status requests are handed off."
        }

    if len(doc_ids) > 0 or len(inv_ids) > 0:
        return {"handoff": "I couldn't confidently match the request to a ledger action."}

    return {"handoff": "No usable invoice or document id was found."}

statusWords = [
    "what's the status",
    "whats the status",
    "status of",
    "has the payment",
    "been scheduled",
    "scheduled yet",
    "been entered yet",
    "entered yet",
    "delete",
    "cancel",
    "cancelling",
    "dispute",
    "disputed",
    "hold the payment",
    "hold payment",
    "hold ",
]

recordWords = [
    "please enter",
    "can you enter",
    "could you enter",
    "enter ",
    "please record",
    "can you record",
    "could you record",
    "record the",
    "record ",
]

scheduleWords = [
    "schedule the payment",
    "schedule payment",
    "schedule the",
    "set up payment",
    "set up the payment",
    "set up payment for",
    "set up the payment for",
    "work out what we owe",
    "pay the invoice",
    "pay invoice",
    "payment for invoice",
    "payment for inv",
]


async def decide(request, kit):
    low = request.lower()

    def hasAny(words):
        for word in words:
            if word in low:
                return True
        return False

    def normalizeId(text, prefix):
        lowerText = text.lower()
        if lowerText.startswith(prefix.lower()):
            digits = ""
            for ch in text:
                if ch >= "0" and ch <= "9":
                    digits = digits + ch
            if digits == "":
                return ""
            return prefix + digits
        if prefix == "DOC-":
            if lowerText.startswith("document ") or lowerText.startswith("doc "):
                digits = ""
                for ch in text:
                    if ch >= "0" and ch <= "9":
                        digits = digits + ch
                if digits == "":
                    return ""
                return prefix + digits
        if prefix == "INV-":
            if lowerText.startswith("invoice ") or lowerText.startswith("inv "):
                digits = ""
                for ch in text:
                    if ch >= "0" and ch <= "9":
                        digits = digits + ch
                if digits == "":
                    return ""
                return prefix + digits
        return ""

    def collectIds(prefix):
        found = []
        if prefix == "DOC-":
            patterns = [
                ("DOC-[0-9]+", request),
                ("doc-[0-9]+", request),
                ("document[ ]+[0-9]+", low),
                ("doc[ ]+[0-9]+", low),
            ]
        else:
            patterns = [
                ("INV-[0-9]+", request),
                ("inv-[0-9]+", request),
                ("invoice[ ]+[0-9]+", low),
                ("inv[ ]+[0-9]+", low),
            ]
        for pattern, text in patterns:
            matches = kit.find(pattern, text)
            for match in matches:
                item = normalizeId(match, prefix)
                if item and item not in found:
                    found.append(item)
        return found

    async def choose(items, kind):
        if len(items) == 1:
            return items[0]
        options = {}
        for item in items:
            options[item] = kind + " candidate"
        options["none"] = "none of them"
        state = {
            "request": request,
            "kind": kind,
            "candidates": items,
        }
        question = {
            "pick": {
                "type": "choice",
                "instructions": "Which " + kind + " does the user mean?",
                "criteria": options,
            }
        }
        answer = await kit.ask(state, question)
        pick = answer["pick"]
        if pick["choice"] == "none":
            return ""
        if pick["choice"] not in items:
            return ""
        if pick["confidence"] < 0.7:
            return ""
        return pick["choice"]

    if hasAny(statusWords):
        return {
            "handoff": "This request is about status, cancellation, or another out-of-scope change."
        }

    recordIntent = hasAny(recordWords)
    scheduleIntent = hasAny(scheduleWords)

    if recordIntent and scheduleIntent:
        return {
            "handoff": "This request mixes invoice entry with payment scheduling."
        }

    if recordIntent:
        docs = collectIds("DOC-")
        if len(docs) == 0:
            return {
                "handoff": "I need a document ID to enter the invoice."
            }
        docId = await choose(docs, "document")
        if not docId:
            return {
                "handoff": "I couldn't identify a single document to enter."
            }
        parsed = await kit.procedure("parse_invoice", doc_id=docId)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {
                "handoff": "I couldn't parse that document as an invoice."
            }
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Invoice recorded in the ledger."
        }

    if scheduleIntent:
        invs = collectIds("INV-")
        if len(invs) == 0:
            return {
                "handoff": "I need an invoice ID to schedule payment."
            }
        invId = await choose(invs, "invoice")
        if not invId:
            return {
                "handoff": "I couldn't identify a single invoice to schedule."
            }
        payable = await kit.procedure("amount_payable", invoice_id=invId)
        if not isinstance(payable, dict) or "error" in payable:
            return {
                "handoff": "I couldn't determine the payable amount for that invoice."
            }
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {
                "handoff": "The payable calculation was missing required fields."
            }
        invoiceId = invId
        if "invoice_id" in payable:
            invoiceId = payable["invoice_id"]
        args = {
            "invoice_id": invoiceId,
            "amount_usd": float(payable["amount_usd"]),
            "pay_on": payable["pay_on"],
        }
        return {
            "action": "schedule_payment",
            "arguments": args,
            "reply": "Payment scheduled."
        }

    return {
        "handoff": "This request does not clearly ask me to enter a vendor invoice or schedule a payment."
    }

docPattern = r'\bDOC-\d{3}\b'
invoicePattern = r'\bINV-\d{3}\b'

statusPatterns = [
    r'\bstatus\b',
    r'\bentered yet\b',
    r'\bbeen entered\b',
    r'\bbeen scheduled\b',
    r'\bscheduled yet\b',
    r'\bhas the payment\b',
    r'\bhas document\b',
    r'\bhas invoice\b'
]

denyPatterns = [
    r'\bdelete\b',
    r'\bcancel\b',
    r'\bdispute\b',
    r'\bhold the payment\b',
    r'\bhold payment\b',
    r'\bkeep it on hold\b',
    r'\bkeep on hold\b'
]

recordPatterns = [
    r'\benter\b',
    r'\bentering\b',
    r'\brecord\b',
    r'\brecording\b'
]

schedulePatterns = [
    r'\bschedule the payment\b',
    r'\bschedule payment\b',
    r'\bset up the payment\b',
    r'\bset up payment\b',
    r'\bpayment for\b',
    r'\bpayment of\b'
]

amountPatterns = [
    r'\bamount due\b',
    r'\bwhat we owe\b',
    r'\bowe on\b',
    r'\bamount payable\b',
    r'\bhow much we owe\b',
    r'\bhow much is due\b'
]

def cleanNumber(value):
    if isinstance(value, float):
        if int(value) == value:
            return int(value)
    return value

def hasAnyPattern(text, patterns, kit):
    for pattern in patterns:
        if len(kit.find(pattern, text)) > 0:
            return True
    return False

def digitsOnly(value):
    out = ""
    for ch in value:
        if ch.isdigit():
            out += ch
    return out

def normalizeId(kind, value):
    if not isinstance(value, str):
        return None
    low = value.lower()
    digits = digitsOnly(value)
    if len(digits) != 3:
        return None
    if low.startswith("inv") or "invoice" in low:
        return "INV-" + digits
    if low.startswith("doc") or "document" in low:
        return "DOC-" + digits
    if kind == "invoice":
        return "INV-" + digits
    if kind == "document":
        return "DOC-" + digits
    return None

def collectIds(text, kind, kit):
    patterns = []
    if kind == "document":
        patterns = [
            r'\bDOC-\d{3}\b',
            r'\bdoc(?:ument)?(?:\s+number)?\s+\d{3}\b'
        ]
    if kind == "invoice":
        patterns = [
            r'\bINV-\d{3}\b',
            r'\binv(?:oice)?(?:\s+number)?\s+\d{3}\b'
        ]
    out = []
    for pattern in patterns:
        matches = kit.find(pattern, text)
        for match in matches:
            normalized = normalizeId(kind, match)
            if normalized is not None and normalized not in out:
                out.append(normalized)
    return out

async def chooseTarget(request, kit, kind, candidates):
    if len(candidates) == 0:
        return None
    if len(candidates) == 1:
        return candidates[0]
    criteria = {}
    for candidate in candidates:
        criteria[candidate] = "the intended " + kind
    criteria["none"] = "none of these"
    state = {"request": request, "kind": kind, "candidates": candidates}
    questions = {
        "target": {
            "type": "choice",
            "instructions": "Choose the single " + kind + " the user intends us to act on. If none of these is the target, choose none.",
            "criteria": criteria
        }
    }
    answer = await kit.ask(state, questions)
    choice = answer["target"]["choice"]
    if choice in candidates:
        return choice
    return None

async def decide(request, kit):
    text = request if isinstance(request, str) else str(request)
    lower = text.lower()

    if hasAnyPattern(lower, statusPatterns, kit) or hasAnyPattern(lower, denyPatterns, kit):
        return {
            "handoff": "This request is about status, cancellation, deletion, dispute, or holding, so it should be handled by the agent."
        }

    docIds = collectIds(text, "document", kit)
    invIds = collectIds(text, "invoice", kit)

    recordIntent = hasAnyPattern(lower, recordPatterns, kit)
    scheduleIntent = hasAnyPattern(lower, schedulePatterns, kit)
    amountIntent = hasAnyPattern(lower, amountPatterns, kit)

    if recordIntent:
        docId = await chooseTarget(request, kit, "document", docIds)
        if docId is None:
            return {
                "handoff": "The document ID is not explicit enough to enter safely."
            }
        parsed = await kit.procedure("parse_invoice", doc_id=docId)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {
                "handoff": "The document could not be parsed safely."
            }
        record = dict(parsed)
        return {
            "action": "record_invoice",
            "arguments": record,
            "reply": "I'll record " + docId + " in the ledger."
        }

    if scheduleIntent:
        invoiceId = await chooseTarget(request, kit, "invoice", invIds)
        if invoiceId is None:
            return {
                "handoff": "The invoice ID is not explicit enough to schedule safely."
            }
        payable = await kit.procedure("amount_payable", invoice_id=invoiceId)
        if not isinstance(payable, dict) or "error" in payable:
            return {
                "handoff": "I could not determine the payable amount safely."
            }
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {
                "handoff": "The payment details are incomplete."
            }
        amount = cleanNumber(payable["amount_usd"])
        payOn = payable["pay_on"]
        return {
            "action": "schedule_payment",
            "arguments": {"invoice_id": invoiceId, "amount_usd": amount, "pay_on": payOn},
            "reply": "I'll schedule payment for " + invoiceId + "."
        }

    if amountIntent:
        invoiceId = await chooseTarget(request, kit, "invoice", invIds)
        if invoiceId is None:
            return {
                "handoff": "The invoice ID is not explicit enough to answer safely."
            }
        payable = await kit.procedure("amount_payable", invoice_id=invoiceId)
        if not isinstance(payable, dict) or "error" in payable:
            return {
                "handoff": "I could not determine the amount due safely."
            }
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {
                "handoff": "The amount-due details are incomplete."
            }
        amount = cleanNumber(payable["amount_usd"])
        payOn = payable["pay_on"]
        return {
            "action": "amount_payable",
            "arguments": {"invoice_id": invoiceId},
            "reply": "Amount due for " + invoiceId + " is $" + str(amount) + " on " + str(payOn) + "."
        }

    return {
        "handoff": "I can only enter explicit vendor invoices into the ledger, schedule explicit invoice payments, or answer explicit amount-due questions."
    }

