"""Program synthesis: build a conservative decision program from judged runs, then tighten it using practice feedback."""

DRAFT_PROMPT = """{{contract}}

Below are judged runs for this job.

Write a decision program with no language model. Use code for anything code can decide. Use Jev only for genuinely ambiguous judgments that code cannot make. When a request is unclear, approximate, incomplete, or only loosely resembles a seen example, prefer handing off rather than risking a wrong action. Wrong actions are much worse than safe hand-offs.

Learn the exact request patterns, tool names, ids, and safe action boundaries from these runs. Do not over-generalize from near matches or "almost the same" requests; if the match is not confident, hand it off.

{{episodes}}"""

REPAIR_PROMPT = """{{contract}}

This decision program was tried on requests for this job:

```python
{{program}}
```

These requests failed in practice.

Focus especially on false positives: requests where the program took an action but should have handed off. Tighten the decision boundaries so near, vague, approximate, or only-partially-matching requests are handed off unless the contract and the runs make the action clearly safe.

Keep existing correct behavior. Do not broaden the program just to cover more cases if that risks wrong actions.

Failures:
{{failures}}

Rewrite the whole program. Reply with one ```python block that contains the full program."""

ROUNDS = 3
SHOWN_FAILURES = 16


def code_of(reply):
    parts = reply.split("```")
    if len(parts) < 3:
        return reply.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[len("python"):]
    return block.strip() + "\n"


def classify_failure(reason):
    text = reason.lower()
    if "could have been served" in text:
        return "handoff"
    if "should have been handed off" in text:
        return "wrong"
    if "wrong action" in text or "incorrect" in text or "took " in text or "took" in text:
        return "wrong"
    if "handed off" in text or "hand-off" in text or "handoff" in text or "could have done" in text:
        return "handoff"
    return "other"


def failure_block(request, reason, observed):
    text = "Request: " + request + "\nReason: " + reason
    if observed:
        text += "\nObservations: " + str(observed)
    return text


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    program = code_of(await lab.ask(lab.fill(DRAFT_PROMPT, contract=lab.contract, episodes=shown)))
    best = program
    bestscore = -1.0

    for roundnum in range(ROUNDS):
        wrongs = []
        handoffs = []
        score = 0.0

        for task_id in lab.stream():
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            if reward < 1:
                block = failure_block(lab.request(task_id), reason, observed)
                kind = classify_failure(reason)
                if kind == "handoff":
                    handoffs.append(block)
                else:
                    wrongs.append(block)

        lab.note(
            "round " + str(roundnum) +
            ": score " + str(score) +
            ", wrongs " + str(len(wrongs)) +
            ", handoffs " + str(len(handoffs))
        )

        if score > bestscore:
            best = program
            bestscore = score

        if not wrongs and not handoffs:
            break

        failuretext = []
        if wrongs:
            failuretext.append("False positives to eliminate first:\n\n" + "\n\n".join(wrongs[:SHOWN_FAILURES]))
        if handoffs:
            failuretext.append("Possible misses to consider only after tightening false positives:\n\n" + "\n\n".join(handoffs[:SHOWN_FAILURES]))

        program = code_of(
            await lab.ask(
                lab.fill(
                    REPAIR_PROMPT,
                    contract=lab.contract,
                    program=program,
                    failures="\n\n".join(failuretext)
                )
            )
        )

    return best

