DOCPATTERN = "doc-\\d{3}|document\\s+\\d{3}|doc\\s+\\d{3}"
INVPATTERN = "inv-\\d{3}|invoice\\s+\\d{3}|inv\\s+\\d{3}"
RECORDPHRASES = ("please enter", "enter ", "please record", "record ")
SCHEDULEPHRASES = ("please schedule", "schedule the payment", "schedule payment", "please set up", "set up the payment", "set up payment", "work out what we owe")
BADTERMS = ("status", "cancel", "disput", "hold", "delete", "entered yet", "been entered", "been scheduled")
REQUIREDPARSE = ("doc_id", "invoice_number", "po_number", "invoice_date", "subtotal_usd", "freight_usd", "discount_percent", "discount_days", "net_days")

async def decide(request, kit):
    text = request.lower()

    def hasphrase(parts):
        for part in parts:
            if part in text:
                return True
        return False

    def validparse(data):
        if not isinstance(data, dict):
            return False
        if "error" in data:
            return False
        return all(field in data for field in REQUIREDPARSE)

    def dedup(items):
        seen = set()
        kept = []
        for item in items:
            if item not in seen:
                seen.add(item)
                kept.append(item)
        return kept

    def canonical(kind, raw):
        digits = ""
        for ch in raw:
            if ch >= "0" and ch <= "9":
                digits = digits + ch
        if len(digits) >= 3:
            digits = digits[-3:]
        if len(digits) != 3:
            return ""
        if kind == "document":
            return "DOC-" + digits
        return "INV-" + digits

    def extract(kind):
        if kind == "document":
            pattern = DOCPATTERN
            prefix = "document"
        else:
            pattern = INVPATTERN
            prefix = "invoice"
        rawitems = kit.find(pattern, text)
        items = []
        for raw in rawitems:
            value = canonical(prefix, raw)
            if value != "":
                items.append(value)
        return dedup(items)

    async def choose(kind, candidates):
        if len(candidates) == 1:
            return candidates[0]
        state = {"request": request, "candidates": candidates, "kind": kind}
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "the target " + kind + " id"
        criteria["none"] = "none of them"
        questions = {
            "pick": {
                "type": "choice",
                "instructions": "Choose the most likely " + kind + " id the user means. If none fit, choose none.",
                "criteria": criteria
            }
        }
        answer = await kit.ask(state, questions)
        pick = answer.get("pick", {}).get("choice", "none")
        if pick == "none":
            return ""
        return pick

    if hasphrase(BADTERMS):
        return {"handoff": "I can only schedule invoice payments or record vendor invoices."}

    recordintent = hasphrase(RECORDPHRASES)
    scheduleintent = hasphrase(SCHEDULEPHRASES)

    if recordintent and scheduleintent:
        return {"handoff": "I can only handle one ledger entry or one payment schedule at a time."}

    if recordintent:
        candidates = extract("document")
        if len(candidates) == 0:
            return {"handoff": "I need a DOC-### document id to enter a vendor invoice."}
        docid = await choose("document", candidates)
        if docid == "":
            return {"handoff": "I need a clear DOC-### document id to enter."}
        parsed = await kit.procedure("parse_invoice", doc_id=docid)
        if not validparse(parsed):
            return {"handoff": "I couldn't parse that document into a ledger invoice."}
        return {"action": "record_invoice", "arguments": parsed, "reply": "Recorded " + str(docid) + " in the ledger."}

    if scheduleintent:
        candidates = extract("invoice")
        if len(candidates) == 0:
            return {"handoff": "I need an INV-### invoice id to schedule payment."}
        invoiceid = await choose("invoice", candidates)
        if invoiceid == "":
            return {"handoff": "I need a clear INV-### invoice id to schedule."}
        payable = await kit.procedure("amount_payable", invoice_id=invoiceid)
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "I couldn't get the payable amount for that invoice."}
        if "amount_usd" not in payable or "pay_on" not in payable or "invoice_id" not in payable:
            return {"handoff": "I couldn't get the payable amount for that invoice."}
        arguments = {
            "invoice_id": payable["invoice_id"],
            "amount_usd": payable["amount_usd"],
            "pay_on": payable["pay_on"]
        }
        return {"action": "schedule_payment", "arguments": arguments, "reply": "Scheduled payment for " + str(invoiceid) + "."}

    return {"handoff": "I can only schedule invoice payments or record vendor invoices."}

DOC_PATTERN = "DOC-[0-9]+"
DOC_WORD_PATTERN = "DOCUMENT[ ]+[0-9][0-9][0-9]"
INV_PATTERN = "INV-[0-9]+"
INV_WORD_PATTERN = "INVOICE[ ]+[0-9][0-9][0-9]"
INV_SHORT_PATTERN = "INV[ ]+[0-9][0-9][0-9]"

SCHEDULE_PHRASES = [
    "SCHEDULE THE PAYMENT",
    "SCHEDULE PAYMENT",
    "SCHEDULE PAYMENT FOR",
    "SCHEDULE THE PAYMENT FOR",
    "SET UP PAYMENT",
    "SET UP THE PAYMENT",
    "SET UP PAYMENT FOR",
    "SET UP THE PAYMENT OF"
]

async def decide(request, kit):
    upper = request.upper()

    def has_any(phrases):
        for phrase in phrases:
            if upper.find(phrase) >= 0:
                return True
        return False

    def unique(items):
        out = []
        for item in items:
            if item not in out:
                out.append(item)
        return out

    def normalize_document(token):
        if token.find("DOC-") == 0:
            return token
        parts = token.split()
        if len(parts) >= 2 and parts[0] == "DOCUMENT":
            return "DOC-" + parts[1]
        return token

    def normalize_invoice(token):
        if token.find("INV-") == 0:
            return token
        parts = token.split()
        if len(parts) >= 2:
            if parts[0] == "INVOICE":
                return "INV-" + parts[1]
            if parts[0] == "INV":
                return "INV-" + parts[1]
        return token

    async def pick_target(kind, candidates):
        candidates = unique(candidates)
        if len(candidates) == 0:
            return ""
        if len(candidates) == 1:
            return candidates[0]

        criteria = {}
        for candidate in candidates:
            if kind == "document":
                criteria[candidate] = "The user wants document " + candidate + " entered into the ledger."
            else:
                criteria[candidate] = "The user wants invoice " + candidate + " scheduled for payment."
        criteria["none"] = "None of the candidates fits."

        state = {"request": request, "kind": kind, "candidates": candidates}
        questions = {
            "target": {
                "type": "choice",
                "instructions": "Choose the likeliest " + kind + " id the user means, or choose none if nothing fits.",
                "criteria": criteria
            }
        }
        answer = await kit.ask(state, questions)
        choice = answer["target"]["choice"]
        if choice == "none":
            return ""
        if choice not in candidates:
            return ""
        return choice

    if has_any(["STATUS", "CANCEL", "DISPUTE"]):
        return {"handoff": "This request is about something other than scheduling or recording a payment."}

    docs = []
    for token in kit.find(DOC_PATTERN, upper):
        docs.append(token)
    for token in kit.find(DOC_WORD_PATTERN, upper):
        docs.append(normalize_document(token))
    docs = unique(docs)

    invs = []
    for token in kit.find(INV_PATTERN, upper):
        invs.append(normalize_invoice(token))
    for token in kit.find(INV_WORD_PATTERN, upper):
        invs.append(normalize_invoice(token))
    for token in kit.find(INV_SHORT_PATTERN, upper):
        invs.append(normalize_invoice(token))
    invs = unique(invs)

    record_signal = False
    if len(docs) > 0 and has_any(["ENTER", "RECORD"]):
        if has_any(["LEDGER", "VENDOR INVOICE"]):
            record_signal = True

    schedule_signal = False
    if len(invs) > 0 and has_any(SCHEDULE_PHRASES):
        schedule_signal = True

    if record_signal and schedule_signal:
        return {"handoff": "This request appears to ask for more than one desk action."}

    if record_signal:
        doc_id = await pick_target("document", docs)
        if doc_id == "":
            return {"handoff": "I could not determine which document to enter."}

        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "I could not parse that document for ledger entry."}

        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + doc_id + " in the ledger."
        }

    if schedule_signal:
        invoice_id = await pick_target("invoice", invs)
        if invoice_id == "":
            return {"handoff": "I could not determine which invoice to schedule."}

        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "I could not determine the payable amount for that invoice."}

        return {
            "action": "schedule_payment",
            "arguments": payable,
            "reply": "Scheduled payment for " + invoice_id + "."
        }

    return {"handoff": "I can only schedule invoice payments or record vendor invoice documents."}

DOC_PATTERN = "DOC-[0-9]+"
INV_PATTERN = "INV-[0-9]+"
SHORT_PATTERN = "[0-9]+"

RECORD_MARKERS = ("please enter", "enter ", "please record", "record ")
PAY_MARKERS = ("schedule the payment", "schedule payment", "set up the payment", "set up payment")
STATUS_MARKERS = ("been scheduled", "entered yet", "status", "hold", "delete", "cancel", "dispute")


async def decide(request, kit) -> dict:
    text = request.lower()

    def norm(value):
        if isinstance(value, float):
            whole = int(value)
            if value == whole:
                return whole
        return value

    def has_marker(markers):
        for marker in markers:
            if text.find(marker) >= 0:
                return True
        return False

    def distinct(values):
        out = []
        for value in values:
            if value not in out:
                out.append(value)
        return out

    def variants(value, prefix):
        out = [value]
        if value.find("-") >= 0:
            parts = value.split("-")
            tail = parts[len(parts) - 1]
            if tail not in out:
                out.append(tail)
        else:
            prefixed = prefix + "-" + value
            if prefixed not in out:
                out.append(prefixed)
        return out

    async def pick_candidate(kind, candidates):
        candidates = distinct(candidates)
        if len(candidates) == 0:
            return None
        if len(candidates) == 1:
            return candidates[0]
        options = {}
        for candidate in candidates:
            options[candidate] = "this is the referenced " + kind + " id"
        options["none"] = "no clear " + kind + " id"
        judgment = await kit.ask(
            {"request": request, "kind": kind, "candidates": candidates},
            {
                "target": {
                    "type": "choice",
                    "instructions": "Pick the single " + kind + " ID the user means. Choose none if no candidate clearly fits.",
                    "criteria": options
                }
            }
        )
        answer = judgment["target"]
        if answer["choice"] == "none":
            return None
        if answer["choice"] not in candidates:
            return None
        return answer["choice"]

    async def parse_document(doc_id):
        for candidate in variants(doc_id, "DOC"):
            parsed = await kit.procedure("parse_invoice", doc_id=candidate)
            if isinstance(parsed, dict) and "error" not in parsed:
                return parsed
        return None

    async def get_payable(invoice_id):
        for candidate in variants(invoice_id, "INV"):
            payable = await kit.procedure("amount_payable", invoice_id=candidate)
            if isinstance(payable, dict) and "error" not in payable:
                if "amount_usd" in payable and "pay_on" in payable:
                    if "invoice_id" not in payable:
                        payable["invoice_id"] = candidate
                    return payable
        return None

    if has_marker(STATUS_MARKERS):
        return {"handoff": "This looks like a status or other out-of-scope request."}

    record_hit = has_marker(RECORD_MARKERS)
    pay_hit = has_marker(PAY_MARKERS)

    if record_hit and pay_hit:
        return {"handoff": "This request appears to combine more than one task."}

    if record_hit:
        doc_ids = kit.find(DOC_PATTERN, request)
        if len(doc_ids) == 0:
            doc_ids = kit.find(SHORT_PATTERN, request)

        doc_id = await pick_candidate("document", doc_ids)
        if doc_id is None:
            return {"handoff": "I couldn't identify a single document to enter."}

        parsed = await parse_document(doc_id)
        if parsed is None:
            return {"handoff": "The document could not be parsed for ledger entry."}

        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + str(doc_id) + " in the ledger."
        }

    if pay_hit:
        inv_ids = kit.find(INV_PATTERN, request)
        if len(inv_ids) == 0:
            inv_ids = kit.find(SHORT_PATTERN, request)

        invoice_id = await pick_candidate("invoice", inv_ids)
        if invoice_id is None:
            return {"handoff": "I couldn't identify a single invoice to schedule."}

        payable = await get_payable(invoice_id)
        if payable is None:
            return {"handoff": "The amount due could not be determined for that invoice."}

        args = {
            "invoice_id": payable["invoice_id"],
            "amount_usd": norm(payable["amount_usd"]),
            "pay_on": payable["pay_on"]
        }
        return {
            "action": "schedule_payment",
            "arguments": args,
            "reply": "Scheduled payment for " + str(invoice_id) + "."
        }

    return {"handoff": "I can only schedule payment for a specific invoice or enter a specific document into the ledger."}

CONTEXT_WINDOW = 60

async def decide(request, kit):
    def normalize(text):
        chars = []
        for ch in text.upper():
            if ("A" <= ch <= "Z") or ("0" <= ch <= "9"):
                chars.append(ch)
            else:
                chars.append(" ")
        return "".join(chars)

    def has_token(spaced_text, token):
        return (" " + token + " ") in spaced_text

    def digits_only(value):
        digits = []
        for ch in value:
            if "0" <= ch <= "9":
                digits.append(ch)
        return "".join(digits)

    def merge_candidates(first_list, second_list):
        merged = []
        seen = set()
        for candidate in first_list + second_list:
            key = digits_only(candidate)
            if key == "":
                key = candidate.upper()
            if key in seen:
                continue
            seen.add(key)
            merged.append(candidate)
        return merged

    def canonicalize(candidate, kind):
        upper = candidate.upper()
        if upper.startswith("INV-") or upper.startswith("DOC-"):
            return upper
        if kind == "payment":
            return "INV-" + candidate
        return "DOC-" + candidate

    def score_candidate(candidate, text, kind):
        needle = candidate.upper()
        found = False
        best = None
        start = 0

        while True:
            position = text.find(needle, start)
            if position < 0:
                break
            found = True

            left = position - CONTEXT_WINDOW
            if left < 0:
                left = 0
            right = position + len(needle) + CONTEXT_WINDOW
            if right > len(text):
                right = len(text)

            context = text[left:right]
            context_norm = " " + normalize(context) + " "
            score = 0

            if kind == "payment":
                if has_token(context_norm, "SCHEDULE"):
                    score += 6
                if has_token(context_norm, "SET"):
                    score += 3
                if has_token(context_norm, "UP"):
                    score += 3
                if has_token(context_norm, "SETUP"):
                    score += 6
                if has_token(context_norm, "PAYMENT"):
                    score += 5
                if has_token(context_norm, "PAY"):
                    score += 3
                if has_token(context_norm, "OWE"):
                    score += 2
                if has_token(context_norm, "DUE"):
                    score += 2
                if has_token(context_norm, "INVOICE"):
                    score += 2
                if " ONLY ACT ON " in context_norm:
                    score += 4
                if needle.startswith("INV-"):
                    score += 1
                if needle.isdigit():
                    score += 1
            else:
                if has_token(context_norm, "ENTER"):
                    score += 6
                if has_token(context_norm, "RECORD"):
                    score += 6
                if has_token(context_norm, "LEDGER"):
                    score += 5
                if has_token(context_norm, "DOCUMENT"):
                    score += 4
                if has_token(context_norm, "DOC"):
                    score += 4
                if has_token(context_norm, "INVOICE"):
                    score += 1
                if " ONLY ACT ON " in context_norm:
                    score += 4
                if needle.startswith("DOC-"):
                    score += 1
                if needle.isdigit():
                    score += 1

            if (
                " DIFFERENT " in context_norm
                or " NEEDS NOTHING " in context_norm
                or " IGNORE " in context_norm
                or " ANOTHER " in context_norm
                or " WRONG " in context_norm
                or " CANCEL " in context_norm
                or " CANCELED " in context_norm
                or " DISPUTE " in context_norm
                or " STATUS " in context_norm
                or " NOT " in context_norm
                or " DO NOT " in context_norm
                or " DONT " in context_norm
            ):
                score -= 5

            if best is None or score > best:
                best = score

            start = position + 1

        if not found:
            return None
        return best

    async def ask_target(candidates, kind):
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "the explicit target"
        criteria["none"] = "none of the candidates is the target"

        state = {
            "request": request,
            "kind": kind,
            "candidates": candidates
        }

        question = {
            "type": "choice",
            "instructions": (
                "In `request`, identify which item in `candidates` is the explicit "
                + kind
                + " target being acted on. Choose the candidate that is actually "
                + "the one to use for the supported task. If none of the candidates "
                + "is the target, choose none."
            ),
            "criteria": criteria
        }

        try:
            judged = await kit.ask(state, {"target": question})
        except Exception:
            return None

        answer = judged.get("target", {})
        choice = answer.get("choice")
        confidence = answer.get("confidence", 0.0)

        if choice == "none":
            return None
        if choice not in candidates:
            return None
        if confidence < 0.5:
            return None
        return choice

    async def choose_target(candidates, kind):
        if len(candidates) == 0:
            return None

        scored = []
        for candidate in candidates:
            score = score_candidate(candidate, text, kind)
            if score is not None:
                scored.append((candidate, score))

        if len(scored) == 0:
            return None

        best_candidate = None
        best_score = None
        second_score = None
        tie = False

        for candidate, score in scored:
            if best_score is None or score > best_score:
                second_score = best_score
                best_score = score
                best_candidate = candidate
                tie = False
            elif score == best_score:
                tie = True
            elif second_score is None or score > second_score:
                second_score = score

        if len(candidates) == 1:
            if best_score is not None and best_score > 0:
                return canonicalize(best_candidate, kind)
            return None

        need_ask = False
        if best_score is None or best_score <= 0:
            need_ask = True
        elif tie:
            need_ask = True
        elif second_score is not None and (best_score - second_score) <= 1:
            need_ask = True

        if need_ask:
            asked = await ask_target(candidates, kind)
            if asked is not None:
                return canonicalize(asked, kind)
            return None

        return canonicalize(best_candidate, kind)

    text = request.upper()
    norm = " " + normalize(text) + " "

    if (
        has_token(norm, "STATUS")
        or has_token(norm, "CANCEL")
        or has_token(norm, "CANCELED")
        or has_token(norm, "DISPUTE")
    ):
        return {"handoff": "request is about invoice status or a dispute/cancellation"}

    schedule_intent = (
        (has_token(norm, "SCHEDULE") or (has_token(norm, "SET") and has_token(norm, "UP")) or has_token(norm, "SETUP"))
        and (has_token(norm, "PAYMENT") or has_token(norm, "PAY"))
    )

    record_intent = (
        has_token(norm, "ENTER") or has_token(norm, "RECORD")
    ) and (
        has_token(norm, "LEDGER")
        or has_token(norm, "DOCUMENT")
        or has_token(norm, "DOC")
        or has_token(norm, "INVOICE")
    )

    if schedule_intent and record_intent:
        return {"handoff": "request mixes payment scheduling and ledger entry"}

    if schedule_intent:
        candidates = merge_candidates(
            kit.find("INV-[0-9]+", text),
            kit.find("\\b[0-9]{3}\\b", text)
        )

        target = await choose_target(candidates, "payment")
        if target is None:
            return {"handoff": "missing a clear invoice ID"}

        try:
            info = await kit.procedure("amount_payable", invoice_id=target)
        except Exception:
            return {"handoff": "invoice could not be priced for payment scheduling"}

        if not isinstance(info, dict) or "error" in info:
            return {"handoff": "invoice could not be priced for payment scheduling"}

        if "amount_usd" not in info or "pay_on" not in info:
            return {"handoff": "invoice pricing was incomplete"}

        try:
            amount_usd = float(info["amount_usd"])
        except Exception:
            return {"handoff": "invoice pricing was incomplete"}

        pay_on = str(info["pay_on"])
        invoice_id = target
        if "invoice_id" in info and isinstance(info["invoice_id"], str):
            invoice_id = info["invoice_id"]

        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": amount_usd,
                "pay_on": pay_on
            },
            "reply": "Scheduled payment for " + str(invoice_id) + "."
        }

    if record_intent:
        candidates = merge_candidates(
            kit.find("DOC-[0-9]+", text),
            kit.find("\\b[0-9]{3}\\b", text)
        )

        target = await choose_target(candidates, "doc")
        if target is None:
            return {"handoff": "missing a clear document ID"}

        try:
            record = await kit.procedure("parse_invoice", doc_id=target)
        except Exception:
            return {"handoff": "document could not be parsed"}

        if not isinstance(record, dict) or "error" in record:
            return {"handoff": "document could not be parsed"}

        reply_id = target
        if "doc_id" in record:
            reply_id = str(record["doc_id"])

        return {
            "action": "record_invoice",
            "arguments": record,
            "reply": "Recorded " + reply_id + " in the ledger."
        }

    return {"handoff": "request is not a supported payment scheduling or ledger entry task"}

candidate_pattern = "(?:INV-|DOC-|inv-|doc-)?\\d{3}"

async def decide(request, kit):
    text = request.lower()
    ids = kit.find(candidate_pattern, request)

    def clean_number(value):
        if isinstance(value, float):
            value = round(value, 2)
            if int(value) == value:
                return int(value)
        return value

    def normalize_id(kind, raw):
        low = raw.lower()
        if kind == "invoice":
            if low.startswith("inv-"):
                return "INV-" + raw[4:]
            if len(raw) == 3 and raw[0].isdigit():
                return "INV-" + raw
            return raw
        if low.startswith("doc-"):
            return "DOC-" + raw[4:]
        if len(raw) == 3 and raw[0].isdigit():
            return "DOC-" + raw
        return raw

    def kind_candidates(kind):
        selected = []
        for raw in ids:
            low = raw.lower()
            if kind == "invoice":
                if low.startswith("doc-"):
                    continue
                selected.append(raw)
            else:
                if low.startswith("inv-"):
                    continue
                selected.append(raw)
        return selected

    async def choose_id(kind):
        candidates = kind_candidates(kind)
        if len(candidates) == 0:
            return None
        if len(candidates) == 1:
            return normalize_id(kind, candidates[0])
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "the " + kind + " identifier to act on"
        criteria["none"] = "no candidate fits"
        answer = await kit.ask(
            {"request": request, "kind": kind, "candidates": candidates},
            {
                "target": {
                    "type": "choice",
                    "instructions": "Choose the single " + kind + " identifier that the user wants acted on. "
                    + "Prefer the identifier tied to the supported action and ignore distractors; choose none if nothing fits.",
                    "criteria": criteria
                }
            }
        )
        if not isinstance(answer, dict) or "target" not in answer:
            return None
        target = answer["target"]
        if not isinstance(target, dict) or "choice" not in target:
            return None
        picked = target["choice"]
        if picked == "none" or picked not in candidates:
            return None
        return normalize_id(kind, picked)

    if "delete" in text or "cancel" in text or "dispute" in text:
        return {"handoff": "request is for deletion, cancellation, or dispute, which is out of scope"}

    if "status" in text and ("invoice" in text or "payment" in text or "document" in text):
        return {"handoff": "request asks about status, which is out of scope"}

    if "been scheduled" in text or "scheduled yet" in text or "been entered" in text or "entered yet" in text:
        return {"handoff": "request asks whether something has already been scheduled or entered, which is out of scope"}

    schedule_intent = False
    if "schedule" in text and "payment" in text and ("invoice" in text or any(raw.lower().startswith("inv-") for raw in ids)):
        schedule_intent = True
    if "set up" in text and "payment" in text and ("invoice" in text or any(raw.lower().startswith("inv-") for raw in ids)):
        schedule_intent = True
    if "work out what we owe on invoice" in text and "schedule the payment" in text:
        schedule_intent = True

    record_intent = False
    if ("record" in text or "enter" in text) and ("document" in text or "ledger" in text or "invoice" in text or any(raw.lower().startswith("doc-") for raw in ids)):
        record_intent = True

    if schedule_intent and record_intent:
        return {"handoff": "request appears to ask for more than one supported action"}

    if schedule_intent:
        invoice_id = await choose_id("invoice")
        if invoice_id is None:
            return {"handoff": "could not determine which invoice to schedule"}
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "could not determine the payment amount for " + invoice_id}
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "could not determine the payment details for " + invoice_id}
        amount = clean_number(payable["amount_usd"])
        pay_on = payable["pay_on"]
        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": amount,
                "pay_on": pay_on
            },
            "reply": "Scheduled payment for " + invoice_id + " on " + pay_on + "."
        }

    if record_intent:
        doc_id = await choose_id("document")
        if doc_id is None:
            return {"handoff": "could not determine which document to enter"}
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "could not parse " + doc_id + " as a vendor invoice"}
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + doc_id + " in the ledger."
        }

    return {"handoff": "request is not one of the supported payment scheduling or vendor invoice entry actions"}

DOC_PATTERNS = ["DOC[ -]?[0-9]+", "DOCUMENT[ -]?[0-9]+"]
INV_PATTERNS = ["INV[ -]?[0-9]+", "INVOICE[ -]?[0-9]+"]

SCHEDULE_PHRASES = [
    "SCHEDULE THE PAYMENT",
    "SCHEDULE PAYMENT",
    "SET UP THE PAYMENT",
    "SET UP PAYMENT",
    "ARRANGE THE PAYMENT",
    "ARRANGE PAYMENT",
    "PLEASE SCHEDULE THE PAYMENT",
    "PLEASE SCHEDULE PAYMENT",
    "CAN YOU SCHEDULE THE PAYMENT",
    "CAN YOU SCHEDULE PAYMENT",
    "COULD YOU SCHEDULE THE PAYMENT",
    "COULD YOU SCHEDULE PAYMENT",
    "THEN SCHEDULE THE PAYMENT",
    "THEN SCHEDULE PAYMENT"
]

RECORD_PHRASES = [
    "RECORD THE INVOICE",
    "RECORD INVOICE",
    "ENTER THE INVOICE",
    "ENTER INVOICE",
    "ADD THE INVOICE",
    "ADD INVOICE",
    "RECORD THE VENDOR INVOICE",
    "RECORD VENDOR INVOICE",
    "ENTER THE VENDOR INVOICE",
    "ENTER VENDOR INVOICE",
    "ADD THE VENDOR INVOICE",
    "ADD VENDOR INVOICE",
    "RECORD THE INVOICE DOCUMENT",
    "ENTER THE INVOICE DOCUMENT",
    "ADD THE INVOICE DOCUMENT",
    "RECORD THE DOCUMENT",
    "RECORD DOCUMENT",
    "ENTER THE DOCUMENT",
    "ENTER DOCUMENT",
    "ADD THE DOCUMENT",
    "ADD DOCUMENT"
]

RECORD_VERBS = ["ENTER", "RECORD", "ADD", "POST"]

async def decide(request, kit):
    req = request.upper().replace("’", "'").replace("“", '"').replace("”", '"')
    clean = req.replace(",", " ").replace(".", " ").replace("?", " ").replace("!", " ").replace(":", " ").replace(";", " ")
    clean = clean.replace("(", " ").replace(")", " ").replace("\n", " ").replace("\t", " ")

    def digits(text):
        out = ""
        for ch in text:
            if ch >= "0" and ch <= "9":
                out = out + ch
        return out

    def has_phrase(text, phrases):
        for phrase in phrases:
            if phrase in text:
                return True
        return False

    def has_any_term(text, terms):
        for term in terms:
            if term in text:
                return True
        return False

    def scan(patterns, prefix):
        store = {}
        for pat in patterns:
            found = kit.find(pat, req)
            for raw in found:
                d = digits(raw)
                if d != "":
                    key = prefix + "-" + d
                    if key not in store:
                        store[key] = []
                    if raw not in store[key]:
                        store[key].append(raw)
        return store

    async def choose_target(store, kind):
        keys = []
        for key in store:
            keys.append(key)

        if len(keys) == 0:
            return ""

        if len(keys) == 1:
            return keys[0]

        criteria = {}
        for cand in keys:
            criteria[cand] = "the " + kind + " id the request is about"
        criteria["none"] = "no clear single target"

        questions = {
            "target": {
                "type": "choice",
                "instructions": "Choose the most likely " + kind + " id the user wants, or none if there is no clear single target.",
                "criteria": criteria
            }
        }

        try:
            ans = await kit.ask({"request": req, "kind": kind, "candidates": keys}, questions)
        except Exception:
            return ""

        if not isinstance(ans, dict) or "target" not in ans:
            return ""

        target = ans["target"]
        if not isinstance(target, dict):
            return ""

        choice = target.get("choice", "")
        confidence = target.get("confidence", 0.0)

        if choice == "none" or choice not in keys or confidence < 0.7:
            return ""

        return choice

    inv_map = scan(INV_PATTERNS, "INV")
    doc_map = scan(DOC_PATTERNS, "DOC")

    schedule_ok = has_phrase(req, SCHEDULE_PHRASES)

    record_ok = has_phrase(req, RECORD_PHRASES)
    if not record_ok:
        if len(doc_map) > 0 and "LEDGER" in req and has_any_term(req, RECORD_VERBS):
            record_ok = True
        elif len(doc_map) > 0 and "VENDOR INVOICE" in req and ("ENTER" in req or "RECORD" in req or "ADD" in req):
            record_ok = True
        elif len(doc_map) > 0 and "IN THE LEDGER" in req and has_any_term(req, RECORD_VERBS):
            record_ok = True
        elif len(doc_map) > 0 and "INTO THE LEDGER" in req and has_any_term(req, RECORD_VERBS):
            record_ok = True

    inv_choice = ""
    doc_choice = ""

    if schedule_ok:
        inv_choice = await choose_target(inv_map, "invoice")
    if record_ok:
        doc_choice = await choose_target(doc_map, "document")

    if schedule_ok and record_ok:
        return {"handoff": "The request appears to ask for more than one supported action."}

    if schedule_ok:
        if inv_choice == "":
            return {"handoff": "I need one clear invoice target to schedule a payment."}
        try:
            payable = await kit.procedure("amount_payable", invoice_id=inv_choice)
        except Exception:
            return {"handoff": "I couldn't compute the payment for " + inv_choice + "."}
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "I couldn't compute the payment for " + inv_choice + "."}
        if "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "The payment details for " + inv_choice + " were incomplete."}
        args = {
            "invoice_id": inv_choice,
            "amount_usd": float(payable["amount_usd"]),
            "pay_on": str(payable["pay_on"])
        }
        return {"action": "schedule_payment", "arguments": args, "reply": "Scheduled payment for " + inv_choice + "."}

    if record_ok:
        if doc_choice == "":
            return {"handoff": "I need one clear document target to record an invoice."}
        try:
            parsed = await kit.procedure("parse_invoice", doc_id=doc_choice)
        except Exception:
            return {"handoff": "I couldn't parse " + doc_choice + " for ledger entry."}
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "I couldn't parse " + doc_choice + " for ledger entry."}
        return {"action": "record_invoice", "arguments": parsed, "reply": "Recorded " + doc_choice + " in the ledger."}

    return {"handoff": "I can only schedule invoice payments or record vendor invoice documents."}

async def decide(request, kit):
    text = request.upper()

    def normalize(value):
        if isinstance(value, float) and abs(value - int(value)) < 0.0000001:
            return int(value)
        return value

    async def pick_id(kind, candidates):
        if len(candidates) == 0:
            return None
        if len(candidates) == 1:
            return candidates[0]
        state = {"request": request, "kind": kind, "candidates": candidates}
        questions = {
            "target": {
                "type": "choice",
                "instructions": "Given `request`, choose the single " + kind + " id the user explicitly wants acted on from `candidates`. Choose `none` if there is no clear target.",
                "criteria": dict((candidate, "the requested " + kind + " id") for candidate in candidates)
                | {"none": "no clear target"},
            }
        }
        try:
            answer = await kit.ask(state, questions)
        except Exception:
            return None
        choice = answer["target"]["choice"]
        if choice == "none":
            return None
        return choice

    doc_ids = kit.find("DOC-[0-9]+", text)
    invoice_ids = kit.find("INV-[0-9]+", text)

    if "HAS DOCUMENT" in text and "BEEN ENTERED" in text:
        doc_id = await pick_id("document", doc_ids)
        if doc_id is None:
            return {"handoff": "no clear document id to check"}
        try:
            doc = kit.read("read_document", doc_id=doc_id)
        except Exception:
            return {"handoff": "could not check the document"}
        if isinstance(doc, dict) and "text" in doc:
            return {"reply": "Yes, " + doc_id + " has been entered."}
        return {"reply": "No, " + doc_id + " was not found."}

    if ("SCHEDULE THE PAYMENT" in text) or ("SCHEDULE PAYMENT" in text) or ("SET UP THE PAYMENT" in text) or ("SET UP PAYMENT" in text):
        invoice_id = await pick_id("invoice", invoice_ids)
        if invoice_id is None:
            return {"handoff": "no clear invoice id for payment scheduling"}
        try:
            payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        except Exception:
            return {"handoff": "could not determine the payment amount"}
        if not isinstance(payable, dict) or "error" in payable or "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "could not determine the payment amount"}
        amount = normalize(payable["amount_usd"])
        pay_on = payable["pay_on"]
        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": amount,
                "pay_on": pay_on,
            },
            "reply": "Scheduled payment for " + invoice_id + ".",
        }

    if (("ENTER " in text) or ("RECORD " in text)) and len(doc_ids) > 0:
        doc_id = await pick_id("document", doc_ids)
        if doc_id is None:
            return {"handoff": "no clear document id for recording"}
        try:
            parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        except Exception:
            return {"handoff": "could not parse the document"}
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "could not parse the document"}
        needed = ["invoice_number", "po_number", "invoice_date", "subtotal_usd", "freight_usd", "discount_percent", "discount_days", "net_days"]
        for key in needed:
            if key not in parsed:
                return {"handoff": "could not parse the document"}
        arguments = {
            "doc_id": doc_id,
            "invoice_number": parsed["invoice_number"],
            "po_number": parsed["po_number"],
            "invoice_date": parsed["invoice_date"],
            "subtotal_usd": parsed["subtotal_usd"],
            "freight_usd": normalize(parsed["freight_usd"]),
            "discount_percent": normalize(parsed["discount_percent"]),
            "discount_days": parsed["discount_days"],
            "net_days": parsed["net_days"],
        }
        return {
            "action": "record_invoice",
            "arguments": arguments,
            "reply": "Recorded " + doc_id + " in the ledger.",
        }

    if ("AMOUNT DUE" in text) or ("WHAT WE OWE" in text) or ("WHAT DO WE OWE" in text) or ("OWE ON" in text):
        invoice_id = await pick_id("invoice", invoice_ids)
        if invoice_id is None:
            return {"handoff": "no clear invoice id for the amount due request"}
        try:
            payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        except Exception:
            return {"handoff": "could not determine the amount due"}
        if not isinstance(payable, dict) or "error" in payable or "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "could not determine the amount due"}
        amount = payable["amount_usd"]
        pay_on = payable["pay_on"]
        return {"reply": "Amount due on " + invoice_id + " is $" + str(amount) + " and is due on " + pay_on + "."}

    if ("STATUS OF INVOICE" in text) or ("WHAT'S THE STATUS OF INVOICE" in text) or ("WHAT IS THE STATUS OF INVOICE" in text):
        invoice_id = await pick_id("invoice", invoice_ids)
        if invoice_id is None:
            return {"handoff": "no clear invoice id for the status request"}
        try:
            invoice = kit.read("read_invoice", invoice_id=invoice_id)
        except Exception:
            return {"handoff": "could not read the invoice"}
        if not isinstance(invoice, dict) or "error" in invoice:
            return {"handoff": "could not read the invoice"}
        try:
            payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        except Exception:
            return {"handoff": "could not determine the invoice status"}
        if not isinstance(payable, dict) or "error" in payable or "amount_usd" not in payable or "pay_on" not in payable:
            return {"handoff": "could not determine the invoice status"}
        amount = payable["amount_usd"]
        pay_on = payable["pay_on"]
        return {"reply": "Invoice " + invoice_id + " is for $" + str(amount) + " and is due on " + pay_on + "."}

    return {"handoff": "request is outside the supported actions"}

DOC_PATTERNS = ["[Dd][Oo][Cc]-[0-9]+", "[Dd][Oo][Cc]\\s+[0-9]+", "[Dd][Oo][Cc][Uu][Mm][Ee][Nn][Tt]\\s+[0-9]+"]
INVOICE_PATTERNS = ["[Ii][Nn][Vv]-[0-9]+", "[Ii][Nn][Vv]\\s+[0-9]+", "[Ii][Nn][Vv][Oo][Ii][Cc][Ee]\\s+[0-9]+"]

async def decide(request, kit):
    text = request if isinstance(request, str) else str(request)
    low = text.lower()

    def unique(values):
        out = []
        seen = set()
        for value in values:
            if value not in seen:
                seen.add(value)
                out.append(value)
        return out

    def normalize(raw):
        raw = raw.strip()
        low_raw = raw.lower()
        if "-" in raw and (low_raw.startswith("doc-") or low_raw.startswith("inv-")):
            parts = raw.split("-")
            if len(parts) >= 2:
                return parts[0].upper() + "-" + parts[1]
        parts = raw.split()
        if len(parts) >= 2:
            head = parts[0].lower()
            if head == "doc" or head == "document":
                return parts[-1]
            if head == "inv" or head == "invoice":
                return parts[-1]
        return raw

    def find_candidates(patterns):
        found = []
        for pattern in patterns:
            matches = kit.find(pattern, text)
            for match in matches:
                found.append(normalize(match))
        return unique(found)

    def variants(identifier, kind):
        base = identifier.strip()
        out = [base]
        low_base = base.lower()

        if base.isdigit():
            if kind == "doc":
                out.append("DOC-" + base)
                out.append("DOC " + base)
                out.append("DOCUMENT " + base)
            else:
                out.append("INV-" + base)
                out.append("INV " + base)
                out.append("INVOICE " + base)
        else:
            if low_base.startswith("doc-"):
                digits = base.split("-")[-1]
                out.append(digits)
                out.append("DOC " + digits)
                out.append("DOCUMENT " + digits)
            if low_base.startswith("inv-"):
                digits = base.split("-")[-1]
                out.append(digits)
                out.append("INV " + digits)
                out.append("INVOICE " + digits)

        return unique(out)

    async def choose(candidates, kind):
        if len(candidates) == 1:
            return candidates[0]
        if len(candidates) == 0:
            return None
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = "act on " + candidate
        criteria["none"] = "no candidate fits"
        answers = await kit.ask(
            {"request": text, "kind": kind, "candidates": candidates},
            {
                "pick": {
                    "type": "choice",
                    "instructions": "Choose the identifier the request wants acted on. If none fits, choose none.",
                    "criteria": criteria,
                }
            },
        )
        answer = answers["pick"]
        choice = answer["choice"]
        confidence = answer["confidence"]
        if choice in candidates and confidence >= 0.5:
            return choice
        return None

    async def parse_document(doc_id):
        for candidate in variants(doc_id, "doc"):
            try:
                parsed = await kit.procedure("parse_invoice", doc_id=candidate)
            except Exception:
                continue
            if isinstance(parsed, dict) and "error" not in parsed:
                return parsed, candidate
        return None, None

    async def calculate_payment(invoice_id):
        for candidate in variants(invoice_id, "invoice"):
            try:
                payable = await kit.procedure("amount_payable", invoice_id=candidate)
            except Exception:
                continue
            if not isinstance(payable, dict):
                continue
            if "error" in payable:
                continue
            if "amount_usd" not in payable or "pay_on" not in payable:
                continue
            try:
                amount = float(payable["amount_usd"])
            except Exception:
                continue
            return {
                "invoice_id": candidate,
                "amount_usd": amount,
                "pay_on": str(payable["pay_on"]),
            }
        return None

    schedule = (len(kit.find("\\bschedule\\b", low)) > 0 or len(kit.find("\\bset\\s+up\\b", low)) > 0 or len(kit.find("\\bowe\\b", low)) > 0) and ("payment" in low)
    record = (len(kit.find("\\benter\\b", low)) > 0 or len(kit.find("\\brecord\\b", low)) > 0) and (("ledger" in low) or ("invoice" in low) or ("document" in low) or ("doc" in low))

    if schedule:
        invoice_candidates = find_candidates(INVOICE_PATTERNS)
        invoice_id = await choose(invoice_candidates, "invoice")
        if invoice_id is None:
            return {"handoff": "I couldn't identify which invoice payment to schedule."}
        payable = await calculate_payment(invoice_id)
        if payable is None:
            return {"handoff": "I couldn't calculate the payable amount for " + invoice_id + "."}
        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": payable["invoice_id"],
                "amount_usd": payable["amount_usd"],
                "pay_on": payable["pay_on"],
            },
            "reply": "Scheduled payment for " + invoice_id + ".",
        }

    if record:
        doc_candidates = find_candidates(DOC_PATTERNS)
        doc_id = await choose(doc_candidates, "document")
        if doc_id is None:
            return {"handoff": "I couldn't identify which document to record."}
        parsed, used_doc_id = await parse_document(doc_id)
        if parsed is None:
            return {"handoff": "I couldn't parse document " + doc_id + "."}
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + doc_id + ".",
        }

    return {"handoff": "This request is not a supported invoice payment or ledger-entry task."}
